public str getName()
{
    return fieldPName(WHSInventTable, RFDescription2);
}

public Set getAllowedValues()
{
    var            ret = new Set(Types::String);
    WHSInventTable wHSInventTable;

    while select wHSInventTable
        group by RFDescription2
    {
        if (! ret.in(wHSInventTable.RFDescription2))
        {
            ret.add(wHSInventTable.RFDescription2);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WHSInventTable, RFDescription2));
    qbr.value(queryValue(_value));
}
